//! Pure runner tests. The SID fixtures were generated by running Bake's
//! TypeScript `packages/sandbox/sandbox-windows-acl/src/workspace-sid.ts`
//! under Node on 2026-10-14; the quoting cases are
//! `packages/subprocess/win32-process/tests/quote.spec.ts`, and the
//! argument errors follow `runner.ts`'s `parseArgs`.

use std::ffi::OsString;
use std::path::Path;

use super::*;

#[test]
fn capability_sids_match_the_typescript_derivation() {
    for (path, sid) in [
        (r"C:\Users\agent\repo", "S-1-4-907248133-152761708"),
        (r"C:\Repo", "S-1-4-56577848-624009942"),
        (r"c:\repo", "S-1-4-107644614-589178496"),
        (r"C:\Repo\", "S-1-4-131877543-215061957"),
        (r"C:\Users\agent\répo", "S-1-4-46420998-657484556"),
        ("", "S-1-4-46444773-337443993"),
    ] {
        assert_eq!(workspace_write_sid(path), sid, "{path}");
    }
    for (path, sid) in [
        (
            r"C:\Users\agent\AppData\Local\Temp\dsh-abc123",
            "S-1-4-174242848-241453763-1",
        ),
        (r"C:\Temp\dsh-a", "S-1-4-486551534-917162856-1"),
    ] {
        assert_eq!(temp_write_sid(path), sid, "{path}");
    }
    // Domain separation: one path never derives the same SID twice.
    assert_ne!(
        temp_write_sid(r"C:\Temp\dsh-a").trim_end_matches("-1"),
        workspace_write_sid(r"C:\Temp\dsh-a")
    );
}

#[test]
fn the_grant_mask_is_modify_without_dac_or_owner_rights() {
    assert_eq!(GRANT_MASK, 0x0011_0156);
    const WRITE_DAC: u32 = 0x0004_0000;
    const WRITE_OWNER: u32 = 0x0008_0000;
    assert_eq!(GRANT_MASK & (WRITE_DAC | WRITE_OWNER), 0);
}

fn quoted(argument: &str) -> String {
    let units: Vec<u16> = argument.encode_utf16().collect();
    let mut out = Vec::new();
    quote_arg(&units, &mut out);
    String::from_utf16(&out).expect("UTF-16")
}

#[test]
fn arguments_quote_as_command_line_to_argv_reads_them() {
    for (input, expected) in [
        ("", "\"\""),
        ("a", "a"),
        ("a b", "\"a b\""),
        ("a\"b", "\"a\\\"b\""),
        ("a\\b", "a\\b"),
        ("a b\\", "\"a b\\\\\""),
        ("a b\\\\", "\"a b\\\\\\\\\""),
        ("a\\\\\"b", "\"a\\\\\\\\\\\"b\""),
        ("tab\there", "\"tab\there\""),
    ] {
        assert_eq!(quoted(input), expected, "{input:?}");
    }
    let argv: Vec<Vec<u16>> = [r"C:\Program Files\tool.exe", "a b", "c"]
        .iter()
        .map(|arg| arg.encode_utf16().collect())
        .collect();
    assert_eq!(
        String::from_utf16(&build_command_line(&argv)).expect("UTF-16"),
        r#""C:\Program Files\tool.exe" "a b" c"#
    );
}

fn args(list: &[&str]) -> Vec<OsString> {
    list.iter().map(OsString::from).collect()
}

#[test]
fn the_runner_contract_parses_and_rejects_like_typescript() {
    let cli = parse(args(&[
        "--workspace",
        "W",
        "--temp",
        "T",
        "--mode",
        "workspace-write",
        "--",
        "cmd",
        "/c",
        "exit",
    ]))
    .expect("parse");
    assert_eq!(cli.workspace, Path::new("W"));
    assert_eq!(cli.temp, Path::new("T"));
    assert_eq!(cli.mode, RunnerMode::WorkspaceWrite);
    assert_eq!(cli.command, args(&["cmd", "/c", "exit"]));
    // A `--` inside the command belongs to the command.
    let cli = parse(args(&[
        "--mode",
        "read-only",
        "--temp",
        "T",
        "--workspace",
        "W",
        "--",
        "x",
        "--",
        "y",
    ]))
    .expect("parse");
    assert_eq!(cli.mode, RunnerMode::ReadOnly);
    assert_eq!(cli.command, args(&["x", "--", "y"]));

    for (list, error) in [
        (&["--workspace"][..], "missing value after --workspace"),
        (&["--bogus", "x"][..], "unknown argument: --bogus"),
        (
            &["--temp", "T", "--mode", "read-only", "--", "x"][..],
            "missing --workspace",
        ),
        (
            &["--workspace", "W", "--mode", "read-only", "--", "x"][..],
            "missing --temp",
        ),
        (
            &["--workspace", "W", "--temp", "T", "--", "x"][..],
            "unknown mode: undefined",
        ),
        (
            &[
                "--workspace",
                "W",
                "--temp",
                "T",
                "--mode",
                "full",
                "--",
                "x",
            ][..],
            "unknown mode: full",
        ),
        (
            &["--workspace", "W", "--temp", "T", "--mode", "read-only"][..],
            "missing command after --",
        ),
        (
            &[
                "--workspace",
                "W",
                "--temp",
                "T",
                "--mode",
                "read-only",
                "--",
            ][..],
            "missing command after --",
        ),
        (
            &[
                "--workspace",
                "W",
                "--workspace",
                "V",
                "--temp",
                "T",
                "--mode",
                "read-only",
                "--",
                "x",
            ][..],
            "duplicate argument: --workspace",
        ),
    ] {
        assert_eq!(parse(args(list)), Err(error.to_owned()), "{list:?}");
    }
}

#[test]
fn profile_args_name_the_workspace_temp_root_and_mode() {
    assert_eq!(
        runner_profile_args(RunnerMode::ReadOnly, Path::new("W"), Path::new("T")),
        args(&["--workspace", "W", "--temp", "T", "--mode", "read-only"])
    );
}

/// A directory the test owns under the OS temporary directory.
struct Dir(std::path::PathBuf);

impl Dir {
    fn new(label: &str) -> Self {
        use std::sync::atomic::{AtomicUsize, Ordering};
        static NEXT: AtomicUsize = AtomicUsize::new(0);
        let path = std::env::temp_dir().join(format!(
            "bake-acl-unit-{label}-{}-{}",
            std::process::id(),
            NEXT.fetch_add(1, Ordering::Relaxed)
        ));
        std::fs::create_dir_all(&path).expect("dir");
        Self(canonical_path(&path))
    }
}

impl Drop for Dir {
    fn drop(&mut self) {
        let _ = std::fs::remove_dir_all(&self.0);
    }
}

#[test]
fn a_temp_root_in_or_equal_to_the_workspace_is_refused() {
    let workspace = Dir::new("ws");
    let inner = workspace.0.join("tmp");
    std::fs::create_dir(&inner).expect("inner");
    let sibling = Dir::new("tmp");
    assert!(check_temp_root_outside_workspace(&workspace.0, &workspace.0).is_err());
    let error = check_temp_root_outside_workspace(&workspace.0, &inner).expect_err("inside");
    assert!(
        error.starts_with("Windows ACL temp root must be outside the workspace: "),
        "{error}"
    );
    assert_eq!(
        check_temp_root_outside_workspace(&workspace.0, &sibling.0),
        Ok(())
    );
    // A workspace inside the temp root is fine: the private directory is a
    // sibling of it, not a parent.
    assert_eq!(
        check_temp_root_outside_workspace(&inner, &workspace.0),
        Ok(())
    );
}

#[test]
fn runner_directories_must_exist_be_canonical_and_not_links() {
    let dir = Dir::new("check");
    assert_eq!(check_directory("--workspace", &dir.0), Ok(()));
    let missing = dir.0.join("missing");
    assert!(
        check_directory("--workspace", &missing)
            .expect_err("missing")
            .starts_with("--workspace is not an existing directory: ")
    );
    let file = dir.0.join("file");
    std::fs::write(&file, "x").expect("file");
    assert!(check_directory("--temp", &file).is_err());
    let dotted = dir
        .0
        .join(".")
        .join("..")
        .join(dir.0.file_name().expect("name"));
    assert!(
        check_directory("--workspace", &dotted)
            .expect_err("not canonical")
            .contains("is not a canonical path")
    );
    #[cfg(unix)]
    {
        let link = dir.0.join("link");
        std::os::unix::fs::symlink(&dir.0, &link).expect("link");
        assert!(check_directory("--workspace", &link).is_err());
    }
}

#[cfg(not(windows))]
#[test]
fn the_runner_fails_closed_off_windows() {
    let dir = Dir::new("off");
    let ws = dir.0.join("ws");
    std::fs::create_dir(&ws).expect("ws");
    let code = run(vec![
        "--workspace".into(),
        ws.into_os_string(),
        "--temp".into(),
        dir.0.clone().into_os_string(),
        "--mode".into(),
        "read-only".into(),
        "--".into(),
        "true".into(),
    ]);
    assert_eq!(code, RUNNER_FAILURE_EXIT);
    assert_eq!(run(args(&["--bogus"])), RUNNER_FAILURE_EXIT);
}
